package com.bank.wealth.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Max-and-min variant of Kadane: best compounded (product) stretch of multipliers.
public class PortfolioGrowthAnalyzer {
    private static final Logger log = Logger.getLogger(PortfolioGrowthAnalyzer.class.getName());

    public long bestCompoundedStretch(int[] multipliers) {
        if (multipliers == null || multipliers.length == 0) {
            throw new IllegalArgumentException("Multiplier sequence must be non-empty");
        }
        long runMax = multipliers[0];
        long runMin = multipliers[0];
        long globalMax = multipliers[0];

        for (int i = 1; i < multipliers.length; i++) {
            int x = multipliers[i];
            if (x < 0) {
                // A negative flips best and worst: swap before updating.
                long tmp = runMax;
                runMax = runMin;
                runMin = tmp;
                final int day = i;
                log.fine(() -> "Negative multiplier at day " + day + "; swapped max/min");
            }
            runMax = Math.max((long) x, runMax * x);
            runMin = Math.min((long) x, runMin * x);
            globalMax = Math.max(globalMax, runMax);
        }
        final long result = globalMax;
        log.info(() -> "Best compounded stretch over " + Arrays.toString(multipliers)
                + " = " + result);
        return globalMax;
    }
}
