package com.bank.wealth;

import com.bank.wealth.model.Account;
import com.bank.wealth.service.PortfolioGrowthAnalyzer;

import java.math.BigDecimal;
import java.util.Date;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MaxProductSubarrayDemo {
    private static final Logger log = Logger.getLogger(MaxProductSubarrayDemo.class.getName());

    public static void main(String[] args) {
        setupLogging();
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        PortfolioGrowthAnalyzer analyzer = new PortfolioGrowthAnalyzer();

        int[] rajeshMult = {2, 3, -2, 4}; // classic: best is 2*3=6
        log.info(() -> rajesh.getHolderName() + " (" + rajesh.getAccountId() + ") multipliers");
        long r1 = analyzer.bestCompoundedStretch(rajeshMult);
        log.info(() -> rajesh.getHolderName() + " best compounded = " + r1);

        int[] priyaMult = {-2, -3, 7}; // two negatives flip: -2*-3=6, *7=42
        log.info(() -> priya.getHolderName() + " (" + priya.getAccountId() + ") multipliers");
        long r2 = analyzer.bestCompoundedStretch(priyaMult);
        log.info(() -> priya.getHolderName() + " best compounded = " + r2);
    }

    private static void setupLogging() {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.FINE);
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.FINE);
    }

    static class BankLogFormatter extends Formatter {
        @Override
        public String format(LogRecord r) {
            return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                    new Date(r.getMillis()), r.getLevel(), r.getMessage());
        }
    }
}
